// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient, uint128 amount) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        uint256 amt = uint256(amount) % 1 ether;
        vm.assume(amt > 0);

        vm.deal(address(this), amt);
        (bool sent,) = address(c).call{value: amt}("");
        require(sent);
        uint256 before = address(c).balance;
        vm.assume(before == amt);

        vm.deal(caller, 1 wei);
        vm.prank(caller);
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(address(c).balance == before);
        } else {
            assertTrue(address(c).balance <= before);
        }
    }
}
